using System.Buffers.Binary;
using RiftReader2.Application;
using RiftReader2.Domain;
namespace RiftReader2.Live.Tests;
public sealed class CurrentBuildTargetNumericLevelCandidateReaderTests
{
 const ulong M=0x140000000,Manager=0x20000000,Table=0x20010000,Bucket=0x20020000,Chain=0x20030000,Entity=0x20040000,Components=0x20050000,Health=0x20060000,Key=0x80000002CD0034D1;
 [Fact] public void Full64BitKeyUsesTaggedChain(){var s=Fixture();var result=Read(s,()=>Context(s,Key));Assert.Equal(Key,result.TargetKey);Assert.Equal(Entity,result.TargetEntity);Assert.Equal("u80000002CD0034D1",result.TargetUnitId);}
 [Fact] public void WrongHighBitsDoNotMatch(){var s=Fixture();s.Put(Chain,Node(0x10000002CD0034D1,Entity));Assert.Throws<InvalidDataException>(()=>Read(s,()=>Context(s,Key)));}
 [Fact] public void NoGatedTargetIsUnavailable(){var s=Fixture();var result=Read(s,()=>Context(s,null));Assert.Equal("unavailable",result.Status);Assert.Null(result.TargetVitals);}
 [Fact] public void TargetChangeFails(){var s=Fixture();int n=0;Assert.Throws<InvalidDataException>(()=>Read(s,()=>Context(s,++n==1?Key:Key+1)));}
 [Fact] public void ChangedNodeFails(){var s=Fixture();s.Change(Chain,Node(Key,Entity+8));Assert.Throws<InvalidDataException>(()=>Read(s,()=>Context(s,Key)));}
 [Fact] public void TypedContextAndChangedPayload(){var s=Fixture();ConfigureContext(s);var r=ReadContext(s);Assert.Equal("raw-typed-candidate",r.TargetContext!.Status);Assert.Equal(65,r.TargetContext.RawLevel);Assert.True(r.TargetContext.CombatCandidate);s=Fixture();ConfigureContext(s);s.Change(0x20070000+0x100,BitConverter.GetBytes(66));Assert.Throws<InvalidDataException>(()=>ReadContext(s));}
 [Fact] public void AlternatePrimaryAndSecondaryLevels(){var s=Fixture();ConfigureContext(s);ConfigureLevel(s,33);var r=ReadContext(s).TargetContext!;Assert.Equal("alternate-primary",r.LevelBranch);Assert.Equal(33,r.NumericLevelCandidate);s=Fixture();ConfigureContext(s);ConfigureLevel(s,-1);s.Put(0x20080000+0x30,Q(0x200A0000));s.Put(0x200A0000+0x64,BitConverter.GetBytes(44));r=ReadContext(s).TargetContext!;Assert.Equal("alternate-secondary",r.LevelBranch);Assert.Equal(44,r.NumericLevelCandidate);}
 [Fact] public void ChangedAlternateValueRejects(){var s=Fixture();ConfigureContext(s);ConfigureLevel(s,33);s.Change(0x20090000+0x64,BitConverter.GetBytes(34));Assert.Throws<InvalidDataException>(()=>ReadContext(s));}
 static void ConfigureLevel(Fake s,int value){s.Put(M+0x2F58270,BitConverter.GetBytes(1));s.Put(Entity+0x19,[1]);s.Put(Components+8,Q(0x20080000));s.Put(0x20080000+0x28,Q(0x20090000));s.Put(0x20090000+0x64,BitConverter.GetBytes(value));}
 static SelectedTargetObservation ReadContext(Fake s)=>CurrentBuildSelectedTargetCandidateReader.Read(s,_=>Context(s,Key),(session,owner)=>{owner.VerifyUnchanged();return new(session.Identity,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,owner.UnitKey,new("unavailable",null),new("unavailable",null));},false,false,true);
 static void ConfigureContext(Fake s){const ulong o=0x20070000;s.Put(Health+0x40,Q(o));s.Put(o,Q(M+0x2927448));s.Put(M+0x2927488,Q(M+0x19D21E0));s.Put(M+0x34731B0,Q(M+0x2929BD0));s.Put(M+0x2929BD8,Q(M+0x19F4D60));s.Put(o+0x100,BitConverter.GetBytes(65));s.Put(o+0x19D,[1]);}
 static SelectedTargetObservation Read(Fake s,Func<CurrentBuildPlayerContextObservation> ctx)=>CurrentBuildSelectedTargetCandidateReader.Read(s,_=>ctx(),(session,owner)=>{owner.VerifyUnchanged();return new(session.Identity,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,owner.UnitKey,new("unavailable",null),new("unavailable",null));});
 static CurrentBuildPlayerContextObservation Context(Fake s,ulong? key)=>new(s.Identity,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,123,Entity,Health,0,Health,key??0,key.HasValue?"fallback-key-candidate":"override-unavailable",key,null,65,"numeric-getter-candidate",0,"raw-byte-candidate",false);
 static Fake Fixture(){var s=new Fake();s.Put(M+0x33624A8,Q(Manager));s.Put(Manager+0x50,Q(Table));var header=new byte[24];Q(Bucket).CopyTo(header,0);Q(24).CopyTo(header,8);Q(1).CopyTo(header,16);s.Put(Table,header);var head=Node(1,Entity);Q(Chain|1).CopyTo(head,0);s.Put(Bucket,head);s.Put(Chain,Node(Key,Entity));s.Put(M+0x2F57850,BitConverter.GetBytes(0));s.Put(Entity+0x18,[0]);s.Put(Entity+0x78,Q(Components));s.Put(Components,Q(Health));s.Put(Health+0x10,Q(Entity));return s;}
 static byte[] Node(ulong k,ulong e){var b=new byte[24];Q(k).CopyTo(b,8);Q(e).CopyTo(b,16);return b;}static byte[] Q(ulong v){var b=new byte[8];BinaryPrimitives.WriteUInt64LittleEndian(b,v);return b;}
 sealed class Fake:IReadOnlyNativeMemorySession {readonly Dictionary<ulong,byte[]> data=[];readonly Dictionary<ulong,byte[]> changed=[];readonly HashSet<ulong> seen=[];public NativeProcessIdentity Identity{get;}=new(123,456,@"C:\RIFT\rift_x64.exe",CurrentBuildPlayerLookup.GameSha256,M,0x4000000);public void Put(ulong a,byte[] b)=>data[a]=b;public void Change(ulong a,byte[] b)=>changed[a]=b;public NativeReadResult Read(ulong a,int n){var b=!seen.Add(a)&&changed.TryGetValue(a,out var c)?c:data.GetValueOrDefault(a);return b is not null&&b.Length==n?new("success",b.ToArray(),null,null):new("unavailable",[],null,null);}public ValueTask<string?> RevalidateAsync(CancellationToken c)=>ValueTask.FromResult<string?>(null);public ValueTask DisposeAsync()=>ValueTask.CompletedTask;}
}
